// Inspetor read-only da tcc_seeds. Nao grava nada.
// Existe para responder com dado, e nao com hipotese: o que sao as linhas
// inativas, como as origens se distribuem e qual o estado do youtube_slot.
const seeds = $('Ler Seeds').all().map(i => i.json);

const contar = (rows, campo) => {
  const m = {};
  for (const r of rows) {
    const v = r[campo];
    const k = (v === null || v === undefined || v === '') ? '(vazio)' : String(v);
    m[k] = (m[k] || 0) + 1;
  }
  return m;
};

const ativos = seeds.filter(r => r.ativo === true);
const inativos = seeds.filter(r => r.ativo !== true);
const comBuzz = seeds.filter(r => r.coletar_youtube === true);

return [{ json: {
  gerado_em: new Date().toISOString(),
  total: seeds.length,
  colunas: seeds.length ? Object.keys(seeds[0]) : [],
  ativos: ativos.length,
  inativos: inativos.length,
  por_origem: contar(seeds, 'origem'),
  por_origem_somente_ativos: contar(ativos, 'origem'),
  com_youtube: comBuzz.length,
  slot_todos: contar(seeds, 'youtube_slot'),
  slot_entre_os_com_buzz: contar(comBuzz, 'youtube_slot'),
  buzz_sem_slot: comBuzz.filter(r => !r.youtube_slot).map(r => r.termo),
  as_linhas_inativas: inativos.map(r => ({ id: r.id, termo: r.termo, categoria: r.categoria, origem: r.origem, justificativa: String(r.justificativa || '').slice(0, 160) })),
  amostra_com_buzz: comBuzz.slice(0, 3).map(r => ({ id: r.id, termo: r.termo, categoria: r.categoria, origem: r.origem, youtube_slot: r.youtube_slot }))
} }];

// Simula a leitura que o coletor do YouTube faz (mesmas 3 condicoes), sem gastar
// cota nenhuma: aqui so se le a tabela, nao se chama a API. Serve para provar que o
// filtro por slot devolve a metade certa antes de publicar o coletor.
const doSlot = $('Simular Filtro YouTube').all().map(i => i.json);
const slots = new Set(doSlot.map(r => r.youtube_slot));

return [{ json: {
  gerado_em: new Date().toISOString(),
  slot_escolhido_pela_hora: [...slots],
  termos_que_seriam_coletados: doSlot.length,
  custo_em_unidades_de_cota: doSlot.length * 100,
  cabe_nas_10000: doSlot.length * 100 <= 10000,
  algum_sem_slot: doSlot.some(r => !r.youtube_slot),
  categorias: [...new Set(doSlot.map(r => r.categoria))].sort(),
  amostra: doSlot.slice(0, 5).map(r => ({ termo: r.termo, categoria: r.categoria, youtube_slot: r.youtube_slot }))
} }];
